template:
use std::cell::Cell;

fn swap_message(cell: &Cell<String>, new_msg: String) -> String {
    let old = ⟦slot1⟧;
    ⟦slot2⟧;
    old
}

fn main() {
    let c = Cell::new(String::from("first"));
    let prev = swap_message(&c, String::from("second"));
    println!("{} -> {}", prev, c.take());
}

tests:
#[test]
fn swaps_strings() {
    let cell = Cell::new(String::from("alpha"));
    let old = swap_message(&cell, String::from("beta"));
    assert_eq!(old, "alpha");
    assert_eq!(cell.take(), "beta");
}
